import { _decorator, Component, Node, tween } from 'cc';
import { BmfAdditiveLabel } from './BmfAdditiveLabel';
const { ccclass, property } = _decorator;

@ccclass('AdditiveBmfRunScoreTest')
export class AdditiveBmfRunScoreTest extends Component {
    @property({ type: BmfAdditiveLabel })
    private additiveAssembler: BmfAdditiveLabel = null;

    public runScoreTest() {
        let target = new BindTarget();
        let score: number = 100000;

        let scoreRunTween = tween(target)
            .to(6, { score: score }, {
                onUpdate: (v: any, ratio: number) => {
                    let current = Math.floor(score * ratio);
                    this.additiveAssembler.string = current.toString();
                }
            })
            .start();
    }
}

class BindTarget {
    score: number = 0;
}